                    if c.get("released"):   # fill về muộn sau khi đã nhả quota
                        self.shared[o.ticker] = self.shared.get(o.ticker, 0) + delta
                    self._journal("FILL", o, c["oid"], c["[REDACTED]"],
                                  u.avg_price or c["price"])
